WITH flattened AS (SELECT id, host, log_ts, level, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, attr_value) SELECT id, host, log_ts, level, status_code, key, CASE WHEN level RLIKE '^(WARN|DEBUG)$' THEN 'GROUP_B' ELSE 'OTHER_ZONE' END AS level_zone FROM flattened
